import React, {useCallback, useRef} from 'react';
import YagrChart, {type YagrReactRef} from '@gravity-ui/yagr/dist/react';

// Dense time series — ~100 data points for a monitoring-style view
const now = Date.now();
const ONE_MINUTE = 60_000;

function generateTimeline(n: number): number[] {
  return Array.from({length: n}, (_, i) => now - (n - 1 - i) * ONE_MINUTE);
}

function generateSeries(label: string, n: number, base: number, amplitude: number): number[] {
  return Array.from({length: n}, (_, i) => base + Math.sin(i * 0.3) * amplitude + (Math.random() - 0.5) * amplitude * 0.4);
}

const timeline = generateTimeline(100);
const cpuSeries = generateSeries('CPU', 100, 45, 15);
const memSeries = generateSeries('Memory', 100, 60, 10);

const config = {
  timeline,
  series: [
    {data: cpuSeries, name: 'CPU %', color: '#FF3B5C', type: 'line'},
    {data: memSeries, name: 'Memory %', color: '#3B7CFF', type: 'line'},
  ],
  axes: {
    y: {
      label: '%',
      scale: 'auto' as const,
      side: 'left' as const,
    },
  },
  chart: {
    appearance: {
      lineWidth: 1,
    },
    series: {
      type: 'LINE' as const,
    },
  },
  legend: {show: true},
  cursor: {enabled: true},
